["Hooks"] = {
["Initialization"] = "function (modTable)\n    local version = \"12.0\"\n    local profileName = \"MF Plater\"\n    \n    -- Function to print the version info in chat\n    local function AnnouncePlaterProfile()\n        print(\"|cff00ff00[\" .. profileName .. \" v\" .. version .. \"]|r Loaded - Enjoy the UI! <3\")\n        print(\"|cffffcc00Want to support future updates? Join our Patreon! patreon.com/MarcelianAndFlame|r\")\n    end\n    \n    -- Run the function when Plater loads\n    C_Timer.After(2, AnnouncePlaterProfile)\n    \n    \nend\n\n\n",
},
