["Hooks"] = {
["Nameplate Added"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if envTable.UpdateMOPowerBar then\n        envTable.UpdateMOPowerBar(unitId, unitFrame)\n    end\n\n    if C_Timer and C_Timer.After then\n        C_Timer.After(0, function()\n            if unitFrame and envTable and envTable.UpdateMOPowerBar then\n                envTable.UpdateMOPowerBar(unitId, unitFrame)\n            end\n        end)\n    end\nend",
["Cast Start"] = "function (self, unitId, unitFrame, envTable, modTable)\n    local powerBar = unitFrame and unitFrame.powerBar\n    if powerBar then\n        powerBar.__mo_hide = 1\n        powerBar:Hide()\n    end\nend",
["Constructor"] = "function (self, unitId, unitFrame, envTable, modTable)\n    \n    -- =========================\n    -- MF Energy™ (Midnight-safe, STRICT Boss-only)\n \n    -- =========================\n    \n    envTable.Height  = 8\n    envTable.OffsetY = -4\n    envTable.InsetX  = 9\n    \n    -- Use the MO Energy™ look texture\n    envTable.Texture     = \"Interface\\\\TARGETINGFRAME\\\\UI-StatusBar\"\n    envTable.FillColor   = {1, 0.8, 0, 1}\n    envTable.BgColor     = {0.1, 0.1, 0.1, 0.7}\n    envTable.BorderColor = {0, 0, 0, 1}\n    \n    -- Guard helper\n    envTable.IsSafe = function(v)\n        if issecretvalue then\n            return not issecretvalue(v)\n        end\n        return true\n    end\n    \n    -- STRICT boss detection ONLY\n    envTable.IsBossOnly = function(unitFrame)\n        local pLevel = UnitLevel(\"player\")\n        local uLevel = UnitLevel(unitFrame.unit)\n        \n        if envTable.IsSafe(uLevel) and envTable.IsSafe(pLevel) then\n            if uLevel == -1 then\n                return true\n            end\n            if uLevel == (pLevel + 2) then\n                return true\n            end\n        end\n        \n        return false\n    end\n    \n    envTable.UpdateMOPowerBar = function(unitId, unitFrame)\n        local powerBar  = unitFrame and unitFrame.powerBar\n        local healthBar = unitFrame and unitFrame.healthBar\n        if not powerBar or not healthBar then return end\n        \n        -- Boss-only gate\n        if not envTable.IsBossOnly(unitFrame) then\n            powerBar:Hide()\n            return\n        end\n        \n        -- Hide during casts\n        if powerBar.__mo_hide then\n            powerBar:Hide()\n            return\n        end\n        \n        -- Let Plater update power info first\n        powerBar.Settings.ShowAlternatePower = true\n        powerBar:SetUnit(unitFrame.unit)\n        powerBar:UpdatePowerInfo()\n        \n        -- IMPORTANT: re-apply texture/color EVERY update (Plater can override)\n        powerBar:SetStatusBarTexture(envTable.Texture)\n        powerBar:SetStatusBarColor(\n            envTable.FillColor[1],\n            envTable.FillColor[2],\n            envTable.FillColor[3],\n            envTable.FillColor[4]\n        )\n        \n        -- Create visuals ONCE\n        if not powerBar.__mo_styled then\n            powerBar.__mo_styled = true\n            \n            -- Background\n            powerBar.__mo_bg = powerBar:CreateTexture(nil, \"BACKGROUND\", nil, -8)\n            powerBar.__mo_bg:SetAllPoints(powerBar)\n            powerBar.__mo_bg:SetColorTexture(\n                envTable.BgColor[1],\n                envTable.BgColor[2],\n                envTable.BgColor[3],\n                envTable.BgColor[4]\n            )\n            \n            -- Border\n            powerBar.__mo_border = CreateFrame(\"Frame\", nil, powerBar, \"BackdropTemplate\")\n            powerBar.__mo_border:SetPoint(\"TOPLEFT\", -1, 1)\n            powerBar.__mo_border:SetPoint(\"BOTTOMRIGHT\", 1, -1)\n            powerBar.__mo_border:SetBackdrop({\n                    edgeFile = \"Interface\\\\ChatFrame\\\\ChatFrameBackground\",\n                    edgeSize = 1,\n            })\n            powerBar.__mo_border:SetBackdropBorderColor(\n                envTable.BorderColor[1],\n                envTable.BorderColor[2],\n                envTable.BorderColor[3],\n                envTable.BorderColor[4]\n            )\n            \n            -- Text (safe font template) + smaller via SCALE\n            powerBar.__mo_text = powerBar:CreateFontString(nil, \"OVERLAY\", \"GameFontNormalTiny\")\n            powerBar.__mo_text:SetPoint(\"CENTER\", powerBar, \"CENTER\", 0, 0)\n            powerBar.__mo_text:SetTextColor(1, 1, 1, 1)\n            powerBar.__mo_text:SetShadowOffset(1, -1)\n            powerBar.__mo_text:SetShadowColor(0, 0, 0, 1)\n            \n            -- Make it smaller safely (no SetFont)\n            powerBar.__mo_text:SetScale(0.75)  -- try 0.70 / 0.65 if you want even smaller\n            \n            -- Hide Plater defaults\n            if powerBar.border then powerBar.border:Hide() end\n            if powerBar.percentText then powerBar.percentText:Hide() end\n        end\n        \n        -- Layout (shorter than healthbar, centered)\n        powerBar:ClearAllPoints()\n        powerBar:SetPoint(\"TOPLEFT\",  healthBar, \"BOTTOMLEFT\",  envTable.InsetX, envTable.OffsetY)\n        powerBar:SetPoint(\"TOPRIGHT\", healthBar, \"BOTTOMRIGHT\", -envTable.InsetX, envTable.OffsetY)\n        powerBar:SetHeight(envTable.Height)\n        \n        -- Text update\n        if powerBar.__mo_text then\n            local _, maxV = powerBar:GetMinMaxValues()\n            local val = powerBar:GetValue()\n            powerBar.__mo_text:SetText(tostring(val) .. \" / \" .. tostring(maxV))\n        end\n        \n        powerBar:Show()\n    end\nend",
["Nameplate Removed"] = "function (self, unitId, unitFrame, envTable, modTable)\n    local powerBar = unitFrame and unitFrame.powerBar\n    if powerBar then\n        powerBar.__mo_hide = nil\n        powerBar:Hide()\n    end\nend",
["Nameplate Updated"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if envTable.UpdateMOPowerBar then\n        envTable.UpdateMOPowerBar(unitId, unitFrame)\n    end\nend",
["Cast Update"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if envTable.UpdateMOPowerBar then\n        envTable.UpdateMOPowerBar(unitId, unitFrame)\n    end\nend",
["Cast Stop"] = "function (self, unitId, unitFrame, envTable, modTable)\n    local powerBar = unitFrame and unitFrame.powerBar\n    if powerBar then\n        powerBar.__mo_hide = nil\n    end\n    \n    if envTable.UpdateMOPowerBar then\n        envTable.UpdateMOPowerBar(unitId, unitFrame)\n    end\nend",
},
