["UID"] = "0x6984dd2acbf4e",
["Hooks"] = {
["Initialization"] = "function (modTable)\n    modTable.kickIds = {\n        [1] = {[1] = 6552, [2] = 6552, [3] = 6552}, -- Warrior\n        [2] = {[1] = nil, [2] = 96231, [3] = 96231}, -- Paladin\n        [3] = {[1] = 147362, [2] = 147362, [3] = 187707}, -- Hunter\n        [4] = {[1] = 1766, [2] = 1766, [3] = 1766} ,-- Rogue\n        [5] = {[1] = nil, [2] = nil, [3] = 15487}, -- Priest\n        [6] = {[1] = 47528, [2] = 47528, [3] = 47528}, -- Death Knight\n        [7] = {[1] = 57994, [2] = 57994, [3] = 57994}, -- Shaman\n        [8] = {[1] = 2139, [2] = 2139, [3] = 2139}, -- Mage\n        [10] = {[1] = 116705, [2] = nil, [3] = 116705}, -- Monk\n        [11] = {[1] = 78675, [2] = 106839, [3] = 106839, [4] = nil}, -- Druid\n        [12] = {[1] = 183752, [2] = 183752, [3] = 183752}, -- Demon Hunter\n        [13] = {[1] = 351338, [2] = nil, [3] = 351338} -- Evoker\n    }\n    \n    -- Fallback defaults if the script config UI isn't set\n    modTable.__defaultCooldownColor = {0, 0, 0, 0}  -- transparent/black\n    modTable.__defaultReadyColor    = {0, 1, 0, 1}  -- green\n    \n    modTable.__defaultTickColor     = {0, 1, 0, 1}  -- green\n    modTable.__defaultTickWidth     = 2\nend",
["Cast Start"] = "function (self, unitId, unitFrame, envTable, modTable)\n    \n    local spec = GetSpecialization()\n    envTable.spec = spec\n    \n    if envTable.class ~= 9 then\n        envTable.kickId = modTable.kickIds[envTable.class][envTable.spec]\n    else\n        -- Warlocks\n        if C_SpellBook.IsSpellKnown(89766, Enum.SpellBookSpellBank.Pet) then\n            envTable.kickId = 89766\n        elseif C_SpellBook.IsSpellKnown(19647, Enum.SpellBookSpellBank.Pet) then\n            envTable.kickId = 19647\n        elseif C_SpellBook.IsSpellKnownOrInSpellBook(132409) then\n            envTable.kickId = 132409\n        end\n    end\n    \n    if envTable.UpdateCastbar then\n        envTable.UpdateCastbar()\n    end\nend",
["Cast Update"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if envTable.UpdateCastbar then\n        envTable.UpdateCastbar()\n    end\n    \n    local interruptSpellID = envTable.kickId\n    local castbar = unitFrame.castBar\n    if not castbar or not castbar.interruptMarker then\n        return\n    end\n    \n    local castDuration = castbar.durationObject\n    local isChannel = castbar.channeling\n    local interruptDuration = interruptSpellID and C_Spell.GetSpellCooldownDuration(interruptSpellID)\n    \n    if castDuration and interruptDuration then\n        castbar.interruptMarker:SetAlphaFromBoolean(\n            interruptDuration:IsZero(),\n            0,\n            C_CurveUtil.EvaluateColorValueFromBoolean(self.notInterruptible, 0, 1)\n        )\n        \n        castbar.interruptMarker:SetMinMaxValues(castDuration:GetStartTime(), castDuration:GetEndTime())\n        castbar.interruptMarker:SetValue(interruptDuration:GetEndTime())\n        castbar.interruptMarker:Show()\n        \n        if not isChannel and castbar.interruptMarker.mode ~= \"cast\" then\n            castbar.interruptMarker.mode = \"cast\"\n            castbar.interruptMarker:SetReverseFill(false)\n            castbar.interruptMarkerPoint:ClearAllPoints()\n            castbar.interruptMarkerPoint:SetPoint(\"LEFT\", castbar.interruptMarker:GetStatusBarTexture(), \"RIGHT\")\n            castbar.interruptMarkerPoint:SetPoint(\"TOP\", castbar.interruptMarker:GetStatusBarTexture(), \"TOP\")\n            castbar.interruptMarkerPoint:SetPoint(\"BOTTOM\", castbar.interruptMarker:GetStatusBarTexture(), \"BOTTOM\")\n            \n        elseif isChannel and castbar.interruptMarker.mode ~= \"channel\" then\n            castbar.interruptMarker.mode = \"channel\"\n            castbar.interruptMarker:SetReverseFill(true)\n            castbar.interruptMarkerPoint:ClearAllPoints()\n            castbar.interruptMarkerPoint:SetPoint(\"RIGHT\", castbar.interruptMarker:GetStatusBarTexture(), \"LEFT\")\n            castbar.interruptMarkerPoint:SetPoint(\"TOP\", castbar.interruptMarker:GetStatusBarTexture(), \"TOP\")\n            castbar.interruptMarkerPoint:SetPoint(\"BOTTOM\", castbar.interruptMarker:GetStatusBarTexture(), \"BOTTOM\")\n        end\n    else\n        castbar.interruptMarker:Hide()\n    end\nend",
["Constructor"] = "function (self, unitId, unitFrame, envTable, modTable)\n    \n    envTable.class = select(3, UnitClass(\"player\"))\n    \n    -- Border thickness tweak (unchanged)\n    if unitFrame.castBar\n    and unitFrame.castBar.FrameOverlay\n    and not unitFrame.castBar.FrameOverlay.__mf_borderScaled then\n        \n        local backdrop = unitFrame.castBar.FrameOverlay:GetBackdrop()\n        if backdrop and backdrop.edgeFile then\n            backdrop.edgeSize = 1.0 -- <<< THICKNESS\n            unitFrame.castBar.FrameOverlay:SetBackdrop(backdrop)\n            unitFrame.castBar.FrameOverlay.__mf_borderScaled = true\n        end\n    end\n    \n    -- ===== SAFE CONFIG READS () =====\n    local cfg = modTable.config or {}\n    \n    local cooldownTbl = cfg.cooldownColor or modTable.__defaultCooldownColor\n    local readyTbl    = cfg.readyColor    or modTable.__defaultReadyColor\n    \n    local cooldownColor = CreateColor(unpack(cooldownTbl))\n    local readyColor    = CreateColor(unpack(readyTbl))\n    \n    local cooldownR, cooldownG, cooldownB = cooldownColor:GetRGB()\n    local readyR, readyG, readyB = readyColor:GetRGB()\n    \n    envTable.UpdateCastbar = function()\n        if envTable.kickId ~= nil and C_SpellBook.IsSpellKnown(envTable.kickId) then\n            \n            local cooldownInfo = C_Spell.GetSpellCooldownDuration(envTable.kickId)\n            local canInterrupt = cooldownInfo:IsZero()\n            local notInterruptable = unitFrame.castBar.notInterruptible\n            \n            local r = C_CurveUtil.EvaluateColorValueFromBoolean(canInterrupt, readyR, cooldownR)\n            local g = C_CurveUtil.EvaluateColorValueFromBoolean(canInterrupt, readyG, cooldownG)\n            local b = C_CurveUtil.EvaluateColorValueFromBoolean(canInterrupt, readyB, cooldownB)\n            \n            r = C_CurveUtil.EvaluateColorValueFromBoolean(notInterruptable, cooldownR, r)\n            g = C_CurveUtil.EvaluateColorValueFromBoolean(notInterruptable, cooldownG, g)\n            b = C_CurveUtil.EvaluateColorValueFromBoolean(notInterruptable, cooldownB, b)\n            \n            unitFrame.castBar.FrameOverlay:SetBackdropBorderColor(r, g, b, 1)\n        else\n            unitFrame.castBar.FrameOverlay:SetBackdropBorderColor(0, 0, 0, 0)\n        end\n    end\n    \n    -- ===== Tick marker creation (safe config reads) =====\n    local castBar = unitFrame.castBar\n    if castBar and not castBar.interruptMarker then\n        castBar.interruptMarker = CreateFrame(\"StatusBar\", nil, castBar)\n        castBar.interruptMarker:SetStatusBarTexture(\"Interface/Buttons/WHITE8x8\")\n        castBar.interruptMarker:SetStatusBarColor(1, 0, 1, 0)\n        \n        castBar.interruptMarkerPoint = castBar.interruptMarker:CreateTexture()\n        \n        local tickColorStr = cfg.tickColor\n        local tickWidth    = cfg.tickWidth or modTable.__defaultTickWidth\n        \n        local r, g, b, a\n        if tickColorStr then\n            r, g, b, a = Plater:ParseColors(tickColorStr)\n        else\n            r, g, b, a = unpack(modTable.__defaultTickColor)\n        end\n        \n        castBar.interruptMarkerPoint:SetColorTexture(r, g, b, a or 1)\n        castBar.interruptMarkerPoint:SetWidth(tickWidth)\n        castBar.interruptMarkerPoint:SetPoint(\"LEFT\", castBar.interruptMarker:GetStatusBarTexture(), \"RIGHT\")\n        castBar.interruptMarkerPoint:SetPoint(\"TOP\", castBar.interruptMarker:GetStatusBarTexture(), \"TOP\")\n        castBar.interruptMarkerPoint:SetPoint(\"BOTTOM\", castBar.interruptMarker:GetStatusBarTexture(), \"BOTTOM\")\n        \n        castBar.interruptMarker:SetClipsChildren(true)\n        castBar.interruptMarker:SetAllPoints(castBar)\n        castBar.interruptMarker:SetFrameLevel(castBar:GetFrameLevel() + 5)\n    end\nend",
},
