["Hooks"] = {
["Nameplate Added"] = "function (self, unitId, unitFrame, envTable, modTable)\n    -- Clean up old frame if it exists\n    if self.gradientOverlayFrame then\n        self.gradientOverlayFrame:Hide()\n        self.gradientOverlayFrame:SetParent(nil)\n        self.gradientOverlayFrame = nil\n    end\n    \n    -- Create a new frame ABOVE everything\n    local overlayFrame = CreateFrame(\"Frame\", nil, self.healthBar)\n    overlayFrame:SetAllPoints(self.healthBar)\n    overlayFrame:SetFrameLevel(self.healthBar:GetFrameLevel() + 2)\n    \n    \n    -- Create the gradient texture inside that frame\n    local gradient = overlayFrame:CreateTexture(nil, \"ARTWORK\")\n    gradient:SetAllPoints()\n    gradient:SetColorTexture(0, 0, 0, 1)\n    gradient:SetGradient(\"VERTICAL\", {r=0, g=0, b=0, a=0.5}, {r=0, g=0, b=0, a=0})\n    gradient:SetBlendMode(\"BLEND\")\n    \n    -- Store reference\n    self.gradientOverlayFrame = overlayFrame\n    \nend\n\n\n",
},
