ble, cooldownG, g)\n            b = C_CurveUtil.EvaluateColorValueFromBoolean(notInterruptable, cooldownB, b)\n            \n            unitFrame.castBar.FrameOverlay:SetBackdropBorderColor(r, g, b, 1)\n        else\n            unitFrame.castBar.FrameOverlay:SetBackdropBorderColor(0, 0, 0, 0)\n        end\n    end\n    \n    -- ===== Tick marker creation (safe config reads) =====\n    local castBar = unitFrame.castBar\n    if castBar and not castBar.interruptMarker then\n        castBar.interruptMarker = CreateFrame(\"StatusBar\", nil, castBar)\n        castBar.interruptMarker:SetStatusBarTexture(\"Interface/Buttons/WHITE8x8\")\n        castBar.interruptMarker:SetStatusBarColor(1, 0, 1, 0)\n        \n        castBar.interruptMarkerPoint = castBar.interruptMarker:CreateTexture()\n        \n        local tickColorStr = cfg.tickColor\n        local tickWidth    = cfg.tickWidth or modTable.__defaultTickWidth\n        \n        local r, g, b, a\n        if tickColorStr then\n            r, g, b, a = Plater:ParseColors(tickColorStr)\n        else\n            r, g, b, a = unpack(modTable.__defaultTickColor)\n        end\n        \n        castBar.interruptMarkerPoint:SetColorTexture(r, g, b, a or 1)\n        castBar.interruptMarkerPoint:SetWidth(tickWidth)\n        castBar.interruptMarkerPoint:SetPoint(\"LEFT\", castBar.interruptMarker:GetStatusBarTexture(), \"RIGHT\")\n        castBar.interruptMarkerPoint:SetPoint(\"TOP\", castBar.interruptMarker:GetStatusBarTexture(), \"TOP\")\n        castBar.interruptMarkerPoint:SetPoint(\"BOTTOM\", castBar.interruptMarker:GetStatusBarTexture(), \"BOTTOM\")\n        \n        castBar.interruptMarker:SetClipsChildren(true)\n        castBar.interruptMarker:SetAllPoints(castBar)\n        castBar.interruptMarker:SetFrameLevel(castBar:GetFrameLevel() + 5)\n    end\nend",
