{
["OptionsValues"] = {
},
["LastHookEdited"] = "",
["UID"] = "0x69865586a21b14",
["Hooks"] = {
["Cast Start"] = "function (self, unitId, unitFrame, envTable, modTable)\n    local unit = unitId or unitFrame.unit\n    if not unit then return end\n    \n    local castBar = unitFrame.castBar\n    if not castBar then return end\n    \n    local spellId = select(9, UnitCastingInfo(unit)) or select(8, UnitChannelInfo(unit))\n    if not spellId then return end\n    \n    local isImportant = C_Spell.IsSpellImportant(spellId)\n    \n    -- one-time: create dot animation\n    if not unitFrame.MF_ImportantDots then\n        unitFrame.MF_ImportantDots =\n        Plater.PlayDotAnimation(castBar, 6, Plater:ParseColors({255, 255, 255}), 10, 3)\n        unitFrame.MF_ImportantDots:SetAlpha(0)\n    end\n    \n    -- IMPORTANT: use the same call style as the working original code\n    unitFrame.MF_ImportantDots:SetAlphaFromBoolean(isImportant)\n    \n    -- watcher: keep it accurate and hide when cast ends\n    unitFrame.MF_ImpDotsToken = (unitFrame.MF_ImpDotsToken or 0) + 1\n    local token = unitFrame.MF_ImpDotsToken\n    \n    local function Watch()\n        if not unitFrame or unitFrame.MF_ImpDotsToken ~= token then return end\n        if not unitFrame.castBar or not unitFrame.MF_ImportantDots then return end\n        \n        local curSpellId = select(9, UnitCastingInfo(unit)) or select(8, UnitChannelInfo(unit))\n        if not curSpellId then\n            unitFrame.MF_ImportantDots:SetAlpha(0)\n            return\n        end\n        \n        local importantNow = C_Spell.IsSpellImportant(curSpellId)\n        \n        -- again: 1-arg version\n        unitFrame.MF_ImportantDots:SetAlphaFromBoolean(importantNow)\n        \n        C_Timer.After(0.10, Watch)\n    end\n    \n    C_Timer.After(0.10, Watch)\nend",
},
